import React, { useEffect, useMemo, useState } from 'react';
import {
  Box,
  Divider,
  Grid,
  IconButton,
  Paper,
  Stack,
  styled,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';
import CreditCardIcon from '@mui/icons-material/CreditCard';
import PaymentsIcon from '@mui/icons-material/Payments';
import ReceiptIcon from '@mui/icons-material/Receipt';
import CheckCircleOutlineIcon from '@mui/icons-material/CheckCircleOutline';
import ErrorOutlineIcon from '@mui/icons-material/ErrorOutline';
import { useAppDispatch } from '../../../store/hooks';
import { useSelector } from 'react-redux';
import {
  addReceivedMoney,
  addPaymentMethod,
  addBalance,
  addFinalSummaryState,
} from '../store/BasketSlice';
import { selectPaymentMethod } from '../store/BasketSelector';
import useSales from '../useSales';
import { getPriceFormatWithoutCurrency } from '../../../core/utils';
import { HEADER_GRADIENT, appColors } from '../../../theme/appColors';
import { useGetUserQuery } from '../../posApi';
import { IUserInfo } from '../../../core/Interface/user.interface';

/* ── tokens ──────────────────────────────────────────────────────────────── */
const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';

/* ── styled components ───────────────────────────────────────────────────── */
const KeypadBtn = styled(Paper)(() => ({
  alignItems: 'center',
  backgroundColor: '#F1F5F9',
  border: '1px solid #E2E8F0',
  borderRadius: '8px',
  boxShadow: 'none',
  cursor: 'pointer',
  display: 'flex',
  fontSize: 18,
  fontWeight: 700,
  justifyContent: 'center',
  minHeight: 44,
  textAlign: 'center',
  userSelect: 'none',
  '&:hover': { backgroundColor: '#E2E8F0' },
}));

const QuickBtn = styled(Paper)(() => ({
  alignItems: 'center',
  backgroundColor: alpha(TEAL, 0.06),
  border: `1px solid ${alpha(TEAL, 0.18)}`,
  borderRadius: '6px',
  boxShadow: 'none',
  cursor: 'pointer',
  display: 'flex',
  fontSize: 13,
  fontWeight: 600,
  justifyContent: 'center',
  padding: '6px 4px',
  textAlign: 'center',
  userSelect: 'none',
  '&:hover': { backgroundColor: alpha(TEAL, 0.14) },
}));

/* ── payment methods config ──────────────────────────────────────────────── */
const PAYMENT_OPTIONS = [
  {
    accent: '#059669',
    bg: alpha('#059669', 0.07),
    border: alpha('#059669', 0.35),
    Icon: PaymentsIcon,
    label: 'Cash',
    type: 'Cash',
  },
  {
    accent: '#2563EB',
    bg: alpha('#2563EB', 0.07),
    border: alpha('#2563EB', 0.35),
    Icon: CreditCardIcon,
    label: 'Card',
    type: 'Card',
  },
  {
    accent: '#D97706',
    bg: alpha('#D97706', 0.07),
    border: alpha('#D97706', 0.35),
    Icon: ReceiptIcon,
    label: 'Cheque',
    type: 'Cheque',
  },
];

/* ── helper row ──────────────────────────────────────────────────────────── */
const AmountRow: React.FC<{ label: string; value: string; accent?: string }> = ({
  label,
  value,
  accent,
}) => (
  <Box
    sx={{
      alignItems: 'center',
      display: 'flex',
      justifyContent: 'space-between',
      py: 0.35,
    }}
  >
    <Typography
      sx={{
        color: '#64748B',
        fontSize: 11,
        fontWeight: 700,
        letterSpacing: '0.05em',
        textTransform: 'uppercase',
      }}
    >
      {label}
    </Typography>
    <Typography
      sx={{
        color: accent || NAVY,
        fontSize: 13,
        fontVariantNumeric: 'tabular-nums',
        fontWeight: 700,
      }}
    >
      {value}
    </Typography>
  </Box>
);

/* ── component ───────────────────────────────────────────────────────────── */
interface OrderPaymentPanelProps {
  isTablet?: boolean;
}

const OrderPaymentPanel: React.FC<OrderPaymentPanelProps> = ({ isTablet = false }) => {
  const dispatch = useAppDispatch();
  const { calculateSummary } = useSales();
  const paymentMethod = useSelector(selectPaymentMethod);
  const [receivedCache, setReceivedCache] = useState(0);
  const [enterAmount, setEnterAmount] = useState('');

  const { data: companyData } = useGetUserQuery();
  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const ud = companyData.data as IUserInfo;
      if (ud.company.currencyCode) return ud.company.currencyCode;
    }
    return '';
  }, [companyData]);

  const balanceCache = receivedCache - calculateSummary.total;

  /* sync received + balance to Redux so SalesActionLeft / pay() can use them */
  useEffect(() => {
    dispatch(addReceivedMoney(receivedCache));
    dispatch(addBalance(balanceCache));
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [receivedCache, balanceCache]);

  const handlePaymentMethodSelect = (method: string) => {
    dispatch(addPaymentMethod(method));
    if (method === 'Card' || method === 'Cheque') {
      setReceivedCache(calculateSummary.total);
    } else {
      setReceivedCache(0);
    }
  };

  /* default to Cash on mount */
  useEffect(() => {
    handlePaymentMethodSelect('Cash');
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* keypad helpers */
  const addDigit = (d: string) => setEnterAmount((prev) => prev + d);
  const clearInput = () => setEnterAmount('');
  const acceptAmount = () => {
    const n = Number(enterAmount);
    if (!isNaN(n)) setReceivedCache(n);
    setEnterAmount('');
  };

  /* balance display */
  const isPositive = balanceCache >= 0;
  const BalIcon = isPositive ? CheckCircleOutlineIcon : ErrorOutlineIcon;
  const balColor = isPositive ? '#059669' : '#DC2626';
  const balBg    = isPositive ? alpha('#059669', 0.06) : alpha('#DC2626', 0.06);
  const balBord  = isPositive ? alpha('#059669', 0.18) : alpha('#DC2626', 0.18);
  const balLabel = balanceCache > 0 ? 'Change' : balanceCache < 0 ? 'Amount Due' : 'Paid in Full';

  return (
    <Box
      sx={{
        backgroundColor: appColors.white,
        borderRadius: '12px',
        boxShadow: '0 4px 24px rgba(0,20,137,0.14)',
        display: 'flex',
        flexDirection: 'column',
        height: 'calc(100vh - 96px)',
        left: isTablet ? 0 : 'calc(33.333% + 4px)',
        overflow: 'hidden',
        position: 'fixed',
        right: '4px',
      }}
    >
      {/* ── Header ──────────────────────────────────────────────── */}
      <Box
        sx={{
          alignItems: 'center',
          background: HEADER_GRADIENT,
          display: 'flex',
          flex: '0 0 auto',
          gap: 2,
          px: 3,
          py: 1.5,
        }}
      >
        <IconButton
          onClick={() =>
            dispatch(addFinalSummaryState({ finalSummaryStare: false }))
          }
          size="small"
          sx={{
            '&:hover': { background: 'rgba(255,255,255,0.12)' },
            color: 'rgba(255,255,255,0.8)',
          }}
        >
          <ArrowBackIosNewIcon sx={{ fontSize: 16 }} />
        </IconButton>

        <Box>
          <Typography
            sx={{
              color: 'rgba(255,255,255,0.65)',
              fontSize: 11,
              fontWeight: 500,
              letterSpacing: '0.08em',
              textTransform: 'uppercase',
            }}
          >
            Checkout{currencyCode ? ` · ${currencyCode}` : ''}
          </Typography>
          <Typography
            sx={{
              color: '#fff',
              fontSize: 22,
              fontVariantNumeric: 'tabular-nums',
              fontWeight: 900,
              lineHeight: 1.1,
            }}
          >
            {getPriceFormatWithoutCurrency(calculateSummary.total)}
          </Typography>
        </Box>
      </Box>

      {/* ── Body ────────────────────────────────────────────────── */}
      <Box
        sx={{
          display: 'flex',
          flex: 1,
          gap: 0,
          overflow: 'hidden',
        }}
      >
        {/* ── Left: keypad + totals ─────────────────────────────── */}
        <Box
          sx={{
            display: 'flex',
            flex: 1,
            flexDirection: 'column',
            gap: 1.5,
            overflow: 'hidden',
            p: 2,
          }}
        >
          {/* Totals card */}
          <Box
            sx={{
              border: '1px solid #E2E8F0',
              borderRadius: '10px',
              p: 1.5,
            }}
          >
            <AmountRow
              label="Total Due"
              value={getPriceFormatWithoutCurrency(calculateSummary.total)}
            />
            <AmountRow
              accent={TEAL}
              label="Received"
              value={getPriceFormatWithoutCurrency(receivedCache)}
            />
          </Box>

          {/* Balance */}
          <Box
            sx={{
              alignItems: 'center',
              background: balBg,
              border: `1px solid ${balBord}`,
              borderRadius: '10px',
              display: 'flex',
              gap: 1,
              p: '10px 14px',
            }}
          >
            <BalIcon sx={{ color: balColor, fontSize: 20 }} />
            <Box>
              <Typography
                sx={{
                  color: alpha('#64748B', 0.8),
                  fontSize: 10,
                  fontWeight: 700,
                  letterSpacing: '0.06em',
                  textTransform: 'uppercase',
                }}
              >
                {balLabel}
              </Typography>
              <Typography
                sx={{
                  color: balColor,
                  fontSize: 18,
                  fontVariantNumeric: 'tabular-nums',
                  fontWeight: 800,
                }}
              >
                {getPriceFormatWithoutCurrency(Math.abs(balanceCache))}
              </Typography>
            </Box>
          </Box>

          {/* Quick amount buttons */}
          <Grid
            container
            spacing={0.75}
          >
            {[5, 10, 20, 50, 100, 500, 1000, 5000].map((amt) => (
              <Grid
                item
                key={amt}
                xs={3}
              >
                <QuickBtn
                  onClick={() => setReceivedCache(amt)}
                  sx={{ color: NAVY }}
                >
                  {amt}
                </QuickBtn>
              </Grid>
            ))}
          </Grid>

          {/* Amount display */}
          <Box
            sx={{
              background: '#F8FAFC',
              border: '1.5px solid #E2E8F0',
              borderRadius: '8px',
              px: 2,
              py: 0.75,
              textAlign: 'right',
            }}
          >
            <Typography
              sx={{
                color: NAVY,
                fontSize: 20,
                fontVariantNumeric: 'tabular-nums',
                fontWeight: 800,
                minHeight: 28,
              }}
            >
              {enterAmount || '0'}
            </Typography>
          </Box>

          {/* Numeric keypad */}
          <Grid
            container
            spacing={0.75}
          >
            {['9', '8', '7', '6', '5', '4', '3', '2', '1', '00', '0', '.'].map(
              (key) => (
                <Grid
                  item
                  key={key}
                  xs={4}
                >
                  <KeypadBtn
                    onClick={() => addDigit(key)}
                    sx={{ color: NAVY }}
                  >
                    {key}
                  </KeypadBtn>
                </Grid>
              )
            )}
            {/* Clear */}
            <Grid
              item
              xs={4}
            >
              <KeypadBtn
                onClick={clearInput}
                sx={{
                  background: alpha('#DC2626', 0.05),
                  color: '#DC2626',
                }}
              >
                C
              </KeypadBtn>
            </Grid>
            {/* Accept (spans 2 cols) */}
            <Grid
              item
              xs={8}
            >
              <KeypadBtn
                onClick={acceptAmount}
                sx={{
                  background: `linear-gradient(135deg, ${TEAL} 0%, #0c7a7c 100%)`,
                  border: 'none',
                  color: '#fff',
                  height: 44,
                  width: '100%',
                }}
              >
                Accept
              </KeypadBtn>
            </Grid>
          </Grid>
        </Box>

        {/* ── Right: payment method selector ───────────────────── */}
        <Box
          sx={{
            borderLeft: '1px solid #F1F5F9',
            display: 'flex',
            flexDirection: 'column',
            gap: 1.5,
            p: 2,
            width: 180,
          }}
        >
          <Typography
            sx={{
              color: '#64748B',
              fontSize: 11,
              fontWeight: 700,
              letterSpacing: '0.06em',
              textTransform: 'uppercase',
            }}
          >
            Payment Method
          </Typography>

          {PAYMENT_OPTIONS.map(({ type, label, Icon, accent, bg, border }) => {
            const active = paymentMethod === type;
            return (
              <Box
                key={type}
                onClick={() => handlePaymentMethodSelect(type)}
                sx={{
                  '&:hover': { background: bg, borderColor: border },
                  alignItems: 'center',
                  background: active ? bg : '#F8FAFC',
                  border: `2px solid ${active ? border : '#E2E8F0'}`,
                  borderRadius: '10px',
                  cursor: 'pointer',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: 0.5,
                  py: 1.5,
                  transition: 'all 0.15s',
                }}
              >
                <Icon sx={{ color: active ? accent : '#94A3B8', fontSize: 26 }} />
                <Typography
                  sx={{
                    color: active ? '#1E293B' : '#64748B',
                    fontSize: 12,
                    fontWeight: 700,
                  }}
                >
                  {label}
                </Typography>
                {active && (
                  <CheckCircleOutlineIcon
                    sx={{ color: accent, fontSize: 14 }}
                  />
                )}
              </Box>
            );
          })}

          {/* Divider + total summary reconfirm */}
          <Divider sx={{ my: 0.5 }} />
          <Stack
            spacing={0.5}
          >
            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
              <Typography sx={{ color: '#94A3B8', fontSize: 11 }}>Subtotal</Typography>
              <Typography sx={{ color: '#64748B', fontSize: 11, fontVariantNumeric: 'tabular-nums' }}>
                {getPriceFormatWithoutCurrency(calculateSummary.subTotal)}
              </Typography>
            </Box>
            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
              <Typography sx={{ color: '#94A3B8', fontSize: 11 }}>Discount</Typography>
              <Typography sx={{ color: '#EF4444', fontSize: 11, fontVariantNumeric: 'tabular-nums' }}>
                -{getPriceFormatWithoutCurrency(calculateSummary.discount)}
              </Typography>
            </Box>
            <Divider sx={{ my: 0.5 }} />
            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
              <Typography sx={{ color: NAVY, fontSize: 12, fontWeight: 700 }}>Total</Typography>
              <Typography sx={{ color: NAVY, fontSize: 13, fontVariantNumeric: 'tabular-nums', fontWeight: 800 }}>
                {getPriceFormatWithoutCurrency(calculateSummary.total)}
              </Typography>
            </Box>
          </Stack>
        </Box>
      </Box>
    </Box>
  );
};

export default React.memo(OrderPaymentPanel);
