import AnimatedPage from '../../layouts/AnimatedPage';
import { Box, useMediaQuery, useTheme } from '@mui/material';
import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { finalSummaryStare } from './store/BasketSelector';
import OrderLeftPanel from './components/OrderLeftPanel';
import OrderRightPanel from './components/OrderRightPanel';
import OrderPaymentPanel from './components/OrderPaymentPanel';

const PreOrderJewellery = () => {
  const paymentStatus = useSelector(finalSummaryStare);
  const theme = useTheme();
  const isTablet = useMediaQuery(theme.breakpoints.down('md'));
  const [cartOpen, setCartOpen] = useState(false);

  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = prev;
    };
  }, []);

  return (
    <AnimatedPage>
      <Box sx={{ height: '100vh', overflow: 'hidden' }}>
        <OrderLeftPanel
          cartOpen={cartOpen}
          isTablet={isTablet}
          onClose={() => setCartOpen(false)}
        />
        {paymentStatus
          ? <OrderPaymentPanel isTablet={isTablet} />
          : <OrderRightPanel isTablet={isTablet} onCartOpen={() => setCartOpen(true)} />
        }
      </Box>
    </AnimatedPage>
  );
};

export default PreOrderJewellery;
