/* eslint-disable react/display-name */
import React, { useMemo } from 'react';
import {
  Box,
  CardMedia,
  Divider,
  Grid,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import { IPreOrderJewelleryInvoice } from '../../../core/Interface/preOrderJewellery.interface';
import { formatDateTime } from '../../../core/utils';

export const PreOrderInvoice = React.forwardRef<
  HTMLDivElement,
  {
    salesRes: IPreOrderJewelleryInvoice;
    width: number;
    fontSize: number;
    label: string;
    fontWeight?: string;
  }
>(({ salesRes, width, fontSize, label, fontWeight }, ref) => {
  const PreOrderInvoiceDataMemo = useMemo(() => {
    return salesRes;
  }, [salesRes]);

  const getPriceFormat = (amount: number): string => {
    return amount.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  };

  return (
    <Box
      ref={ref}
      sx={{
        //  width: '245px',
        maxWidth: width,
        // pt: '20px',
        pr: '20px',
        pb: '250px',
        pl: '20px',
        overflow: 'scroll',
        breakAfter: 'always',
        breakBefore: 'always',
        breakInside: 'avoid',
      }}
    >
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justify: 'center',
        }}
      >
        <CardMedia
          alt="logo"
          component="img"
          image={PreOrderInvoiceDataMemo.branch.logo}
          sx={{ height: '80px', width: '80px', p: 0, m: 0 }}
        />
        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PreOrderInvoiceDataMemo.branch.headerText1}
        </Typography>
        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PreOrderInvoiceDataMemo.branch.headerText2}
        </Typography>
        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PreOrderInvoiceDataMemo.branch.headerText3}
        </Typography>
        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PreOrderInvoiceDataMemo.branch.email}
        </Typography>
        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PreOrderInvoiceDataMemo.branch.mobile}
        </Typography>

        {/* <Box sx={{ height: '20px' }} /> */}
        <Divider
          flexItem
          orientation="horizontal"
        />
      </Box>
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'left',
        }}
      >
        <Box sx={{ height: '7px' }} />
        {(label === '58mm' || label === '80mm') && (
          <div
            style={{
              display: 'flex',
              flexDirection: 'row',
              gap: '4px',
              textAlign: 'left',
            }}
          >
            <div
              style={{
                flex: '0 0 auto',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'left',
                marginRight: '4px',
              }}
            >
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                Order No
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                Sales By
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                Customer
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                Date
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                Delivery Date
              </Typography>
            </div>
            <div
              style={{
                flex: '0 0 auto',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'flex-end',
                marginRight: '4px',
              }}
            >
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                :
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                :
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                :
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                :
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                :
              </Typography>
            </div>

            <div
              style={{
                flex: '1',
                display: 'flex',
                flexDirection: 'column',
                gap: '0px',
              }}
            >
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                {PreOrderInvoiceDataMemo.orderNo}
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                {PreOrderInvoiceDataMemo.createdBy}
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                {PreOrderInvoiceDataMemo.customerName.name}
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                {formatDateTime(new Date(PreOrderInvoiceDataMemo.dateTime))}
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                {formatDateTime(
                  new Date(PreOrderInvoiceDataMemo.deliveryDateTime)
                )}
              </Typography>
            </div>
          </div>
        )}

        {(label === 'A5' || label === 'A4') && (
          <div
            style={{
              display: 'flex',
              flexDirection: 'row',
              gap: '4px',
              textAlign: 'left',
            }}
          >
            <div
              style={{
                flex: '0 0 auto',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'flex-start',
                marginRight: '4px',
              }}
            >
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                Order No
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                Sales By
              </Typography>
            </div>

            <div
              style={{
                flex: '0 0 auto',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'flex-end',
                marginRight: '4px',
              }}
            >
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                :
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                :
              </Typography>
            </div>

            <div
              style={{
                flex: '1',
                display: 'flex',
                flexDirection: 'column',
                gap: '0px',
              }}
            >
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                {PreOrderInvoiceDataMemo.orderNo}
              </Typography>
              <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                {PreOrderInvoiceDataMemo.createdBy}
              </Typography>
            </div>

            <div
              style={{
                flex: '0 0 auto',
                display: 'flex',

                alignItems: 'flex-end',
              }}
            >
              {' '}
              <div
                style={{
                  flex: '0 0 auto',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'flex-start',
                  marginRight: '4px',
                }}
              >
                <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                  Customer
                </Typography>
                <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                  Date
                </Typography>
              </div>
              <div
                style={{
                  flex: '0 0 auto',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'flex-end', // Ensure right-aligned for customer and date
                  marginLeft: '4px',
                  marginRight: '6px',
                }}
              >
                <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                  :
                </Typography>
                <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                  :
                </Typography>
              </div>
              <div
                style={{
                  flex: '1',
                  display: 'flex',
                  alignItems: 'flex-start',
                  flexDirection: 'column',
                  gap: '0px',
                }}
              >
                <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                  {PreOrderInvoiceDataMemo.customerName.name}
                </Typography>
                <Typography sx={{ fontSize: fontSize, fontWeight: fontWeight }}>
                  {formatDateTime(new Date(PreOrderInvoiceDataMemo.dateTime))}
                </Typography>
              </div>
            </div>
          </div>
        )}

        <Divider
          flexItem
          orientation="horizontal"
        />
      </Box>

      {(label === '58mm' || label === '80mm') && (
        <TableContainer sx={{ maxWidth: width }}>
          <Table sx={{ width: '100%' }}>
            <TableHead sx={{ width: '100%' }}>
              <TableRow>
                <TableCell
                  align="left"
                  sx={{
                    fontSize: fontSize,
                    fontWeight: 800,
                    pl: 0,
                    color: 'black',
                  }}
                >
                  Item
                </TableCell>
                <TableCell
                  align="left"
                  sx={{
                    fontSize: fontSize,
                    fontWeight: 800,
                    color: 'black',
                  }}
                >
                  Dis
                </TableCell>
                <TableCell
                  align="right"
                  sx={{
                    fontSize: fontSize,
                    fontWeight: 800,
                    pr: 0,
                    color: 'black',
                  }}
                >
                  Amount
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {PreOrderInvoiceDataMemo &&
                PreOrderInvoiceDataMemo.items &&
                PreOrderInvoiceDataMemo.items.map((item, index) => (
                  <React.Fragment key={index}>
                    <TableRow sx={{ p: 0, m: 0 }}>
                      <TableCell
                        // colSpan={3}
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          textAlign: 'left',
                          color: 'black',
                          width: '100%',
                          p: 0,
                          m: 0,
                        }}
                      >
                        {item.itemName}
                      </TableCell>
                    </TableRow>
                    <TableRow sx={{ p: 0 }}>
                      <TableCell
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          color: 'black',
                          borderBottom: 'none',
                          p: 0,
                          m: 0,
                        }}
                      >
                        {item.qty} × {getPriceFormat(item.unitPrice)}
                      </TableCell>
                      <TableCell
                        align="left"
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          color: 'black',
                          borderBottom: 'none',
                        }}
                      >
                        {item.isDiscountPercentage
                          ? item.discount + '%'
                          : item.discount}
                      </TableCell>
                      <TableCell
                        align="right"
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          color: 'black',
                          borderBottom: 'none',
                          p: 0,
                          //  pr: '10px', // default zero
                          m: 0,
                        }}
                      >
                        {getPriceFormat(item.amount)}
                      </TableCell>
                    </TableRow>
                  </React.Fragment>
                ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      {(label === 'A4' || label === 'A5') && (
        <TableContainer sx={{ maxWidth: width }}>
          <Table sx={{ width: '100%' }}>
            <TableHead sx={{ width: '100%' }}>
              <TableRow>
                <TableCell
                  align="left"
                  sx={{ fontSize: fontSize, fontWeight: 800, pl: 0 }}
                >
                  Item
                </TableCell>
                <TableCell
                  align="left"
                  sx={{ fontSize: fontSize, fontWeight: 800 }}
                >
                  Qty
                </TableCell>
                <TableCell
                  align="right"
                  sx={{ fontSize: fontSize, fontWeight: 800, pr: '30px' }}
                >
                  Unit Price
                </TableCell>
                <TableCell
                  align="left"
                  sx={{ fontSize: fontSize, fontWeight: 800 }}
                >
                  Dis
                </TableCell>
                <TableCell
                  align="right"
                  sx={{ fontSize: fontSize, fontWeight: 800, pr: 0 }}
                >
                  Amount
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody sx={{ width: '100%' }}>
              {PreOrderInvoiceDataMemo &&
                PreOrderInvoiceDataMemo.items &&
                PreOrderInvoiceDataMemo.items.map((item, index) => (
                  <React.Fragment key={index}>
                    <TableRow sx={{}}>
                      <TableCell
                        // colSpan={3}
                        align="left"
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          textAlign: 'left',
                          pl: 0,
                          // width: '100%',
                          // p: 0,
                          // m: 0,
                        }}
                      >
                        {item.itemName}
                      </TableCell>

                      <TableCell
                        align="left"
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          borderBottom: 'none',
                          // p: 0,
                          // m: 0,
                        }}
                      >
                        {item.qty}
                      </TableCell>
                      <TableCell
                        align="right"
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          borderBottom: 'none',
                          pr: '30px',
                          // p: 0,
                          // m: 0,
                        }}
                      >
                        {getPriceFormat(item.unitPrice)}
                      </TableCell>
                      <TableCell
                        align="left"
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          borderBottom: 'none',
                          // p: 0,
                          // //  pr: '20px',
                          // m: 0,
                        }}
                      >
                        {item.isDiscountPercentage
                          ? item.discount + '%'
                          : getPriceFormat(item.discount)}
                      </TableCell>
                      <TableCell
                        align="right"
                        sx={{
                          fontSize: fontSize,
                          fontWeight: fontWeight,
                          borderBottom: 'none',
                          pr: 0,
                          // p: 0,
                          // //  pr: '10px', // default zero
                          // m: 0,
                        }}
                      >
                        {getPriceFormat(item.amount)}
                      </TableCell>
                    </TableRow>
                  </React.Fragment>
                ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      <Divider
        flexItem
        orientation="horizontal"
      />
      <Grid
        container
        spacing={2}
      >
        <Grid
          item
          xs={6}
        >
          <Box>
            <Typography
              fontSize={fontSize}
              fontWeight={fontWeight}
            >
              Sub Total{' '}
            </Typography>
            {PreOrderInvoiceDataMemo.discount > 0 && (
              <Typography
                fontSize={fontSize}
                fontWeight={fontWeight}
              >
                Discount{' '}
                {PreOrderInvoiceDataMemo.isDiscountPercentage
                  ? '( ' + PreOrderInvoiceDataMemo.discount + '% )'
                  : ''}
              </Typography>
            )}
          </Box>
        </Grid>
        <Grid
          item
          xs={6}
        >
          <Box sx={{ mb: '10px', textAlign: 'right' }}>
            <Typography
              fontSize={fontSize}
              fontWeight={fontWeight}
            >
              {getPriceFormat(PreOrderInvoiceDataMemo.subTotal)}
            </Typography>
            {PreOrderInvoiceDataMemo.discount > 0 && (
              <Typography
                fontSize={fontSize}
                fontWeight={fontWeight}
              >
                {getPriceFormat(PreOrderInvoiceDataMemo.discount)}
              </Typography>
            )}
          </Box>
        </Grid>
      </Grid>
      <Divider
        flexItem
        orientation="horizontal"
        sx={{ border: '1px dashed #E0E0E0' }}
      />
      <Grid
        container
        spacing={2}
      >
        <Grid
          item
          xs={6}
        >
          <Box>
            <Typography
              fontSize={fontSize}
              fontWeight={fontWeight}
            >
              Total
            </Typography>
          </Box>
        </Grid>
        <Grid
          item
          xs={6}
        >
          <Box sx={{ textAlign: 'right' }}>
            <Typography
              fontSize={fontSize}
              fontWeight={fontWeight}
            >
              {getPriceFormat(PreOrderInvoiceDataMemo.subTotal)}
            </Typography>
          </Box>
        </Grid>
      </Grid>
      <Grid
        container
        spacing={2}
      >
        <Grid
          item
          xs={6}
        >
          <Box>
            <Typography
              fontSize={fontSize}
              fontWeight={fontWeight}
            >
              Received
            </Typography>
          </Box>
        </Grid>
        <Grid
          item
          xs={6}
        >
          <Box sx={{ textAlign: 'right' }}>
            <Typography
              fontSize={fontSize}
              fontWeight={fontWeight}
            >
              {getPriceFormat(PreOrderInvoiceDataMemo.received)}
            </Typography>
          </Box>
        </Grid>
      </Grid>

      {/* {(PreOrderInvoiceDataMemo.balance ?? 0) > 0 && (
        <Grid
          container
          spacing={2}
        >
          <Grid
            item
            xs={6}
          >
            <Box>
              <Typography
                fontSize={fontSize}
                fontWeight={fontWeight}
              >
                Return
              </Typography>
            </Box>
          </Grid>
          <Grid
            item
            xs={6}
          >
            <Box sx={{ textAlign: 'right' }}>
              <Typography
                fontSize={fontSize}
                fontWeight={fontWeight}
              >
                {getPriceFormat(PreOrderInvoiceDataMemo.received ?? 0)} -{' '}
                {getPriceFormat(PreOrderInvoiceDataMemo.subTotal)}
              </Typography>
            </Box>
          </Grid>
        </Grid>
      )} */}
      <Grid
        container
        spacing={2}
      >
        <Grid
          item
          xs={6}
        >
          <Box>
            {PreOrderInvoiceDataMemo.balance < 0 ? (
              <Typography
                fontSize={fontSize}
                fontWeight={fontWeight}
              >
                Due
              </Typography>
            ) : (
              <Typography
                fontSize={fontSize}
                fontWeight={fontWeight}
              >
                Balance
              </Typography>
            )}
          </Box>
        </Grid>
        <Grid
          item
          xs={6}
        >
          <Box sx={{ textAlign: 'right' }}>
            <Typography
              fontSize={fontSize}
              fontWeight={fontWeight}
            >
              {getPriceFormat(PreOrderInvoiceDataMemo.balance)}
            </Typography>
          </Box>
        </Grid>
      </Grid>
      <Divider
        flexItem
        orientation="horizontal"
        sx={{ border: '1px dashed #E0E0E0' }}
      />
      <Box sx={{ height: '10px' }} />
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
        }}
      >
        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PreOrderInvoiceDataMemo.branch.footerText1}
        </Typography>
        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PreOrderInvoiceDataMemo.branch.footerText2}
        </Typography>

        <Typography
          align="center"
          sx={{ fontSize: fontSize, fontWeight: fontWeight }}
        >
          {PreOrderInvoiceDataMemo.branch.footerText3}
        </Typography>
      </Box>
    </Box>
  );
});
